entries[31809] = { ["name"] = "Zauberstab des ewigen Hains", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Beschwört einige Urtümer des ewigen Hains, die Euch 2.50 Min. lang im Kampf gegen die Eredar zur Seite zu stehen. Um diese Fähigkeit einzusetzen, muss Baelmon der Hundehetzer anvisiert sein und ihr müsst Euch in einem Radius von 30 um ihn herum befinden.\n1 Aufladung" }
