entries[31856] = { ["name"] = "Dunkelmond-Karte: Kreuzzug", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 70\nAnlegen: Jedes Mal, wenn Ihr einem Gegner Nahkampf- oder Distanzschaden zufügt, wird Eure Angriffskraft 10 Sek. lang um 6 erhöht. Dieser Effekt ist bis zu 20 Mal stapelbar. Jedes Mal, wenn Ihr einen schädlichen Zauber auf einen Gegner wirkt, wird Euer Zauberschaden 10 Sek. lang um 8 erhöht. Dieser Effekt ist bis zu 10-mal stapelbar.\nVerkaufspreis:" }
entries[31857] = { ["name"] = "Dunkelmond-Karte: Zorn", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 70\nAnlegen: Jedes Mal, wenn einer Eurer direkt Schaden verursachenden Angriffe nicht kritisch trifft, werden 10 Sek. lang Eure kritische Trefferwertung um 17 und Eure kritische Zaubertrefferwertung um 17 erhöht. Ein von Euch zugefügter kritischer Treffer verbraucht den Effekt.\nVerkaufspreis:" }
entries[31858] = { ["name"] = "Dunkelmond-Karte: Vergeltung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\n+51 Ausdauer\nBenötigt Stufe 70\nAnlegen: Wenn Ihr von einem Angriff oder schädlichen Zauber getroffen werdet, besteht eine Chance von 10% bei Eurem Angreifer 95 bis 115 Heiligschaden zu verursachen. (Procchance: 10%)\nVerkaufspreis:" }
entries[31859] = { ["name"] = "Dunkelmond-Karte: Wahnsinn", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\n+51 Ausdauer\nBenötigt Stufe 70\nAnlegen: Jedesmal, wenn Ihr einem Gegner einen Todesstoß versetzt, der Erfahrung oder Ehre gewährt, erhaltet Ihr die Macht des Wahnsinns.\nVerkaufspreis:" }
